188		rejectRequest(request_id: string, error: Error): boolean {
189			const pending = this.pendingRequests.get(request_id);
190			if (!pending) {
191				logger.warn(LogType.CLUSTER, `Cannot reject unknown request ${request_id}`);
192				return false;
193			}
194	
195			clearTimeout(pending.timeout);
196			this.pendingRequests.delete(request_id);
197			this.onSettle?.(request_id);
198	
199			logger.error(LogType.CLUSTER, `Request ${request_id} rejected:`, error);
200	
201			pending.reject(error);
202			return true;
203		}
204	
205		/**
206		 * Get the number of pending requests
207		 */
208		getPendingCount(): number {
209			return this.pendingRequests.size;
210		}
211	
212		/**
213		 * Clear all pending requests (useful for testing or shutdown)
214		 */
215		clearAll(): void {
216			for (const pending of this.pendingRequests.values()) {
217				clearTimeout(pending.timeout);
218				pending.reject(new Error("Request tracker cleared"));
219			}
220			this.pendingRequests.clear();
221			this.lateSuccesses.clear();
222			logger.info(LogType.CLUSTER, "All pending requests cleared");
223		}
224	}
