		call: grpc.ServerUnaryCall<any, any>,
		callback: grpc.sendUnaryData<any>,
		event: IPCEvent,
		data: Record<string, unknown>,
		guild_id?: string
	) {
		try {
			const { meta } = call.request;

			const responsePromise = this.requestTracker.trackRequest(meta.trace_id);

			let clusterId =
				this.clusterIPC.pickConnectedCluster(ChannelGrpcService.FALLBACK_CLUSTER_ID) ??
				ChannelGrpcService.FALLBACK_CLUSTER_ID;
			if (guild_id) {
				const shardId = Shards.getShardIdFromguild_id(guild_id, this.totalShards);
				clusterId = this.clusterIPC.getClusterIdForShard(shardId);
			}

			const delivered = this.clusterIPC.sendToCluster(
				clusterId,
				{
					type: event,
					source: Source.MASTER,
					request_id: meta.trace_id,
					data
				},
				() =>
					this.requestTracker.rejectRequest(
						meta.trace_id,
						new Error(`Cluster ${clusterId} died mid-flight for ${event}`)
					)
			);
			if (!delivered) {
				this.requestTracker.rejectRequest(
					meta.trace_id,
					new Error(`Cluster ${clusterId} unreachable for ${event}`)
				);
			}

			const response = await responsePromise;

			callback(null, {
				success: response.success,
				code: response.code,
				message: response.message,
				data: response.data || {},
				meta: response.meta || {},
				timestamp: response.timestamp,
				request_id: meta.trace_id
			});
		} catch (err) {
			this.logger.error(LogType.GRPC, "ChannelGrpcService error", err);
			reportError(err, { layer: "grpc", operation: "ChannelGrpcService", source: "INTERNAL" });

			callback(null, {
				success: false,
				code: "INTERNAL",
				message: err instanceof Error ? err.message : "Failed to forward channel action",
				data: {},
				meta: {},
				timestamp: new Date().toISOString(),
				request_id: call.request?.meta?.trace_id || ""
			});
		}
	}
