// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

const MAX_PENDING = 1000;

/**
 * `pendingRequests` had no ceiling — a stalled worker (or a cluster that
 * never comes back) let the map grow without bound, retaining a resolve/
 * reject closure and a `Timeout` per in-flight request. This pins the fix:
 * once the tracker hits its cap, new requests are rejected immediately
 * instead of being queued forever.
 */
describe("RequestTracker — pendingRequests has a ceiling", () => {
	let tracker: InstanceType<typeof RequestTracker>;

	beforeEach(() => {
		vi.useFakeTimers();
		tracker = new RequestTracker(30000);
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects a new request once the tracker is at capacity", async () => {
		const promises: Promise<unknown>[] = [];
		for (let i = 0; i < MAX_PENDING; i++) {
			promises.push(tracker.trackRequest(`trace-${i}`).catch(() => {}));
		}
		expect(tracker.getPendingCount()).toBe(MAX_PENDING);

		await expect(tracker.trackRequest("trace-overflow")).rejects.toThrow(/at capacity/);
		// The overflowing request must not have been added to the map.
		expect(tracker.getPendingCount()).toBe(MAX_PENDING);

		await Promise.all(promises);
	});

	it("accepts new requests again once pending ones settle below the cap", async () => {
		const promises: Promise<unknown>[] = [];
		for (let i = 0; i < MAX_PENDING; i++) {
			promises.push(tracker.trackRequest(`trace-${i}`).catch(() => {}));
		}

		tracker.resolveRequest("trace-0", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-0"
		} as any);
		expect(tracker.getPendingCount()).toBe(MAX_PENDING - 1);

		const accepted = tracker.trackRequest("trace-fresh", 1000);
		expect(tracker.getPendingCount()).toBe(MAX_PENDING);

		tracker.resolveRequest("trace-fresh", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-fresh"
		} as any);
		await expect(accepted).resolves.toMatchObject({ success: true });

		await Promise.all(promises);
	});
});

